"""Author a native Foundry v14 chapter 11 adventure catalogue; no world DB writes."""
from pathlib import Path
import json, copy, re, hashlib
from PIL import Image

ROOT=Path(__file__).resolve().parents[1]
SYSTEM=ROOT/'through-the-breach'
ID='through-the-breach'
ART=f'systems/{ID}/assets/adventure/chapter11/'
catalog=json.loads((SYSTEM/'data/bestiary.json').read_text(encoding='utf-8'))['entries']
def profile(name):
    data=copy.deepcopy(next(e['data'] for e in catalog if e['data']['name']==name))
    data.pop('_id',None);data['flags']={};return data
def page(name,html,sort=0):return {'name':name,'type':'text','sort':sort,'title':{'show':True,'level':1},'text':{'content':html,'format':1},'ownership':{'default':-1}}
def journal(key,name,html,folder='gm',images=()):
    pages=[page(name,html)]
    for i,(title,src) in enumerate(images):pages.append({'name':title,'type':'image','src':src,'sort':(i+1)*100000,'ownership':{'default':-1}})
    return {'key':key,'folder':folder,'data':{'name':name,'ownership':{'default':0},'pages':pages}}
def prose(text):return '<p>'+text+'</p>'
def ul(*items):return '<ul>'+''.join('<li>'+i+'</li>' for i in items)+'</ul>'
def header(title):return '<h2>'+title+'</h2>'
def readout(text):return '<blockquote><p>'+text+'</p></blockquote>'
def source(p):return prose(f'<em>Основная книга, глава 11, печатная стр. {p}; PDF на 2 страницы дальше. Текст ниже — адаптация для ведения, а не дословная копия.</em>')

mar=profile('Марионетка');mar['name']='Марионетка Сессы';mar['system']['notes']+='\n\nГлава 11, стр. 409–410: одна марионетка на Сужденного. Одно Очко Судьбы ведётся мастером вручную. При 0 ранениях или ниже: критический эффект, затем неподвижна. Тянущиеся струны и укрытия разрешаются по описанию.'
cesar=profile('Пароходчик');cesar['name']='Сезар Армати';cesar['img']=ART+'cesar.png';cesar['prototypeToken']['texture']['src']=ART+'cesar-token.svg';cesar['prototypeToken']['disposition']=0
cesar['system']['notes']='Основная книга, глава 11, стр. 411–413. Профиль Пароходчика (стр. 386), без «Взрывателя» и «Моё творение». Закован в кандалы; не нападает первым, кроме самообороны. Провал переговоров: последующие СЛ +1.\nМагические действия и их масти мастер разрешает по описанию. Рамка нейтральная: вступление в Арканисты — возможный будущий итог.'
cesar['system']['characteristics']='Живой, Человек';cesar['system']['conditions']='Прикован к полу; освобождение требует ключей.'
for item in cesar['items']:
    item['system']['description']=re.sub(r'Взрыватель:.*?(?=\(1\))','',item['system'].get('description',''),flags=re.S)
