guard=profile('Гвардеец гильдии');guard['name']='Тело гвардейца Гильдии';guard['system'].update(dead=True,unconscious=True);guard['system']['wounds']['value']=0;guard['system']['notes']='Реквизит сцены 2. Основная книга, стр. 412: убит электрической магией Сезара, обгоревший мундир и частично оплавленная винтовка. Это не живой участник боя.'
vito={'name':'Вито Сесса','type':'npc','img':ART+'vito.png','ownership':{'default':0},'system':{'rank':0,'rankDefense':False,'characteristics':'Живой, Человек','notes':'Основная книга, стр. 408–409. Худой, сгорбленный кукловод около шестидесяти лет. Огромный чемодан с надписью «Удивительный Сесса». Исчезает вместе с пассажирами при входе в Пролом. Книга не задаёт ему боевого профиля: это портретный NPC, базовые числовые поля не являются характеристиками из книги.'},'prototypeToken':{'actorLink':False,'texture':{'src':ART+'vito-token.svg'},'disposition':0,'displayName':20,'bar1':{'attribute':None}}}
actors=[{'key':k,'folder':f,'data':d} for k,f,d in [('vito','people',vito),('cesar','people',cesar),('marionette','opponents',mar),('guard','props',guard)]]

guide=source('408–413')+header('Подготовка за пять минут')+ul(
    'Приключение рассчитано примерно на час после создания персонажей. Дайте игрокам время обсудить решения; объясняйте последствия, а не подменяйте правила ради победы.',
    'Откройте сцену {ttb:scene:prologue}. Сужденные знакомятся в третьем пассажирском вагоне «Железного барана». В Прологе не флипают карты.',
    'После знакомства проведите обычный «Конец пролога»: каждому участвующему Сужденному три карты из личной Смешанной колоды. Выберите именно участников, а не тестовых актёров.',
    'Макрос «Приключение 11 — расставить марионеток» создаёт по одному скрытому противнику на Сужденного в боевой сцене. Укажите число игроков; их жетоны перетащите в пассажирский вагон самостоятельно.',
    'Инициативу начните при выходе кукол. Стремления и выдачу карт за их способности напоминайте игрокам.',
    'В сцене 2 можно сразу идти к двигателю: обязательного разговора с Сезаром нет.',
    'При успехе финала проведите обычный эпилог. В учебном приключении книга разрешает желающим пересмотреть Навыки после знакомства с игрой.')
guide+=header('Навигация')+ul('{ttb:journal:prologue}','{ttb:journal:passengers}','{ttb:journal:prison}','{ttb:journal:engine}','{ttb:journal:endings}','{ttb:journal:reference}')
guide+=header('Карта и видимость')+prose('Карта — новая иллюстрированная схема трёх игровых участков, а не точный план или полная длина поезда. Слева двигатель, посередине пассажирский вагон, справа каторжный. Между третьим вагоном и локомотивом в рассказе остаются другие вагоны; схема сокращает этот переход. Одна клетка = 1 ярд. Сцены не активируются автоматически. NPC и заметки доступны только мастеру. Иллюстрации из папки «Для показа» можно открыть и явно показать игрокам, не раскрывая журнал мастера.')
guide+=header('Повторная установка')+prose('Импорт добавляет отсутствующие документы; изменения мастера и существующие жетоны сохраняются. Макрос расстановки не создаёт ещё один набор, если марионетки уже есть. Три кнопки приключения лежат в папке Макросов.')
prolog=source('408–409')+header('Для чтения или пересказа')+readout('После многочасовой очереди на жаркой гильдейской станции Проломтауна вас пропускают в «Железного барана». Внутри неожиданно холодно. Вы занимаете места на обращённых друг к другу скамьях в передней части третьего вагона. Над сиденьями сталь испещрена глубокими царапинами, напоминающими следы когтей.')+header('Что дать игрокам')+ul('Попросите каждого назвать персонажа и описать внешность. Дайте им поговорить и познакомиться.','Напомните о выбранном Стремлении на эту сессию. Карточных проверок здесь нет.','В конце Пролога — три карты Руки контроля каждому участнику.')+prose('{ttb:scene:prologue} · {ttb:actor:vito}')
passengers=source('408–410')+header('Чемодан Сессы')+readout('Когда проводник закрывает двери и помогает с багажом, худой пожилой пассажир напротив пытается поднять непомерно большой чемодан. От усилия и неловкости на его лице проступает отчаяние.')+ul('Помощь: Атлетика СЛ 8. Успех — чемодан убран наверх. Все, кто пытался помочь, независимо от успеха замечают надпись «Удивительный Сесса».','Если никто не помогает, проводник требует второй билет для чемодана; тот занимает соседнее сиденье.','Задержку поезда Сесса объясняет погрузкой каторжников для шахт. Затем свисток, движение к серебристо-голубому Пролому.')
passengers+=header('Между мирами')+readout('Боль и головокружение накрывают вас при входе в сияние. Через мгновение остальные пассажиры исчезли. Поезд застыл; нет ни гула двигателя, ни стука колёс. В окна льётся серебристо-голубой свет. Тишину нарушает только скрежет из оставленного чемодана.')+ul('Марионетки ожили от сырой магии Пролома. Одна на каждого Сужденного. Струны тянутся за ними; их облик может быть комическим или страшным.','Чемодан на сиденье: крышка открывается сразу. Убран наверх: книга позволяет несколько выстрелов, пока он стучит, падает и куклы вырываются. Точное число выстрелов не задано — не назначайте фиксированный бесплатный раунд автоматически.','Начните Драматическое время и инициативу. Марионетки — Миньоны ранга 5, без флипа карты на обычные проверки; ранг уже включён в суммы в скобках книги.','Сиденья дают жёсткое укрытие: − к флипу z-атаки и её урона. Перелезание через них — Трудная местность, двойной расход движения. Эти условные штрафы и движение задаёт мастер.','Захват нитей разрешайте по способности «Тянущиеся струны» из профиля Марионетки. У каждой одно Очко Судьбы — ручной учёт мастером.','При 0 ранениях или ниже — критический эффект, затем кукла неподвижна. После последней победы завершите Драматическое время: игроки могут сбросить любое число карт и добрать до трёх.')+prose('{ttb:actor:marionette} · {ttb:scene:train}')
prison=source('410–412')+header('Крик из заднего вагона')+readout('После боя в тишине слышится человеческий крик из вагона позади вас. У задней двери можно различить странный приглушённый треск.')+ul('Слух СЛ 9 у задней двери: удаётся услышать электрический треск. Сезар убивает не исчезнувшего охранника.','Остаться — ничего не происходит, окна закрыты на болты. Идти вперёд — сразу сцена двигателя. Исследовать крик — каторжный вагон.')+header('Вход')+readout('Переход между вагонами залит ярким светом; в пустоте движется нечто чужое. В вагоне-тюрьме вдоль стен деревянные скамьи, а из пола поднимаются цепи. У двери дымится тело гвардейца с оплавленной винтовкой. Мужчина с тяжёлой квадратной челюстью и светящимися глазами поднимает скованные руки и просит помочь.')+header('Секрет и характер Сезара')+prose('Ирландский убийца и вор, переданный Гильдии на каторгу. При проходе через Пролом обрёл магию; его желание остановить поезд удерживает всех между мирами. Убил охранника током, но не способен освободить себя; тело вне досягаемости. Дружелюбие натянутое, характер вспыльчивый. Первым не нападает, кроме самообороны.')
prison+=header('Социальные проверки')+'<table><thead><tr><th>Навык</th><th>Базовая СЛ</th><th>Результат</th></tr></thead><tbody>'+''.join(f'<tr><td>{skill}</td><td>{tn}</td><td>{effect}</td></tr>' for skill,tn,effect in [('Контроль',8,'Сезар ненадёжен; отдельное чтение мотивов после обещания помощи показывает, что он не разбирается в поездах.'),('Бартер',8,'Перемирие в обмен на ключи от оков.'),('Очарование',8,'Рассмешить и расположить его к группе.'),('Запугивание',13,'Убедить не связываться с группой.'),('Обман',8,'Убедить в выбранной неправде.')])+'</tbody></table>'+prose('<strong>После каждого проваленного Соревнования с Сезаром все последующие СЛ с ним растут на +1.</strong> Счётчик: ____ провалов. Неудачная проверка Слуха до разговора не является Соревнованием с ним.')+prose('Успех любого из этих Соревнований позволяет узнать о приливе сил и желании остановить двигатель. Освобождение или обещание освободить вызывает предложение помочь запустить поезд; он не знает, как тот устроен. Статы — Пароходчик, без «Моё творение» и «Взрыватель»; заклинательные действия разрешайте вручную по карточке.')+prose('{ttb:actor:cesar} · {ttb:actor:guard} · {ttb:scene:prison}')
engine=source('413')+header('Пустой двигатель')+readout('В машинном отделении никто не отвечает. Механизмы молчат, в широкие окна льётся холодное сияние, а за ним угадываются огромные щупальца. Двигатель выглядит достаточно просто: если разжечь котёл и правильно запустить механизмы, поезд сможет двинуться.')+header('Перезапустить поезд!')+ul('СЛ каждого Соревнования: 8.','Разрешённые навыки в списке книги: Атлетика, Инженерия, Колдовство; указан Интеллект. Для этого задания выбирайте Интеллект в диалоге проверки.','Длительность одного интервала: 5 минут, а не ограничение всего испытания. Каждый участник обычно делает одну проверку за интервал; при незавершённой задаче начинается следующий.','Требование успеха: 2 × число Сужденных. Требование катастрофического провала: 1 × число Сужденных.','Успешное Соревнование даёт 1 успех, плюс по одному за каждый Предел Успеха (полные 5 превышения). Обычная неудача без Пределов Провала прогресс не меняет; каждый Предел Провала приближает катастрофу. См. стр. 290.','Не нужно использовать каждый разрешённый навык. Уголь и температура — физическая работа; управление — Инженерия; магическое пламя — Колдовство.')+header('Лист учёта мастера')+prose('Сужденных: ____ · цель успехов: ____ · предел провалов: ____<br>Интервал (5 минут): ____ · успехи: ____ · Пределы Провала: ____<br>Кто / навык / итог / вклад: ____________________________________')+header('Неоднозначность русского текста')+prose('Пояснение упоминает Кузнеца, но список разрешённых навыков его не содержит. Это не четвёртый автоматически разрешённый навык. Если хотите разрешить Кузнечное дело, примите явное решение мастера и объявите группе.')+header('Последний шанс')+prose('При первой катастрофе двигатель серьёзно повреждён. Одна проверка Артефактинга СЛ 14 позволяет отремонтировать его и повторить Текущее Соревнование. Неудачный ремонт или катастрофа второй попытки ведут к ужасному финалу. Книга не задаёт альтернативных обходов; творческие решения обсуждайте как решения мастера.')+prose('{ttb:scene:engine} · {ttb:journal:endings}')
endings=source('413')+header('Успешный запуск')+readout('Котёл оживает, колёса начинают двигаться. Поезд разгоняется и выходит из сияния в Малифо. Гильдейский инженер успевает вскочить на локомотив и остановить его.')+ul('Сезар освобождён и группа не выдаёт его: изображает попутчика, возможно Вито Сессу, если слышал имя. Позднее может стать союзником, присоединившись к Арканистам.','Сезар выдан либо остался в оковах: Гильдия берёт его под стражу и, обнаружив способности, превращает в Колдуна-преследователя.','В обоих случаях успешного запуска Сужденные добрались до Малифо.')+header('Ужасный конец')+readout('Двигатель разрывается от неудачного ремонта. Пар кричит в пустоту между мирами. Громадное щупальцеобразное существо поворачивается на этот звук и приближается к неподвижному поезду. Путешествие окончено: никто не узнает, что произошло с пассажирами.')+header('Эпилог и продолжение')+prose('Проведите обычный эпилог системы: выбранные мастером навыки для развития, опыт и шаг Стремления — по правилам эпилога. Не добавляйте произвольную денежную награду: в главе она не задана. В учебной сессии разрешено пересмотреть Навыки после знакомства с системой. Запишите судьбу Сезара и отношение героев к Гильдии — это зацепки продолжения.')
reference=source('408–413')+header('Быстрые проверки')+'<table><tr><th>Ситуация</th><th>Навык</th><th>СЛ</th></tr><tr><td>Убрать чемодан</td><td>Атлетика</td><td>8</td></tr><tr><td>Треск за дверью</td><td>Слух</td><td>9</td></tr><tr><td>Сезар</td><td>Контроль / Бартер / Очарование / Обман</td><td>8 + провалы</td></tr><tr><td>Сезар</td><td>Запугивание</td><td>13 + провалы</td></tr><tr><td>Запуск двигателя</td><td>Атлетика / Инженерия / Колдовство + Интеллект</td><td>8</td></tr><tr><td>Аварийный ремонт</td><td>Артефактинг</td><td>14</td></tr></table>'+header('Границы автоматизации')+ul('Инициатива, обычные проверки, оружейная атака, урон и сознание — штатными кнопками системы.','Сиденья: жёсткое укрытие и Трудная местность применяются вручную. Геометрические стены блокируют движение, но не назначают укрытие.','Очко Судьбы марионетки, её струны, магические действия Сезара, накопление успехов/Пределов Провала и +1 СЛ переговоров — учёт мастером.','Масти NPC при противостоянии Сужденному пока контролируются мастером. Не заменяйте обязательную масть простой числовой СЛ.','Сцены и иллюстрации — оригинальная визуальная адаптация. Нельзя считать их каноническими чертежами или внешностью из книги.')
journals=[journal('guide','00 — Начать здесь · журнал мастера',guide),journal('prologue','01 — Пролог · Все на борт!',prolog),journal('passengers','02 — Недисциплинированные пассажиры',passengers),journal('prison','03 — Блюз каторжников',prison),journal('engine','04 — Паровой двигатель',engine),journal('endings','05 — Финалы и эпилог',endings),journal('reference','06 — Проверки и подсказки',reference),journal('show-train','Для показа — Железный баран',prose('«Железный баран» доставит вас через Пролом в Малифо. На время пути вы оказались попутчиками.'),'show',[('Проломтаун и Пролом',ART+'breach.png')]),journal('show-vito','Для показа — Вито Сесса',prose('Пожилой пассажир с огромным чемоданом. Надпись на чемодане можно показывать только после того, как персонажи её заметили.'),'show',[('Вито Сесса',ART+'vito.png')]),journal('show-cesar','Для показа — Мужчина в оковах',prose('Скованный человек в полосатой каторжной форме. Показать при входе в вагон-тюрьму.'),'show',[('Мужчина в оковах',ART+'cesar.png')])]

def walls():
    result=[]
    # Measured against the original generated image; scene displays it at 2x resolution.
    for left,right,top,bottom in [(92,665,164,510),(748,1438,164,510),(1510,2108,164,510)]:
        mid=(top+bottom)//2
        for x1,y1,x2,y2 in [(left,top,right,top),(left,bottom,right,bottom),(left,top,left,mid-40),(left,mid+40,left,bottom),(right,top,right,mid-40),(right,mid+40,right,bottom)]:
            result.append({'c':[x1*2,y1*2,x2*2,y2*2],'move':20,'sight':0,'light':0,'sound':0})
        for x in [left,right]:result.append({'c':[x*2,(mid-40)*2,x*2,(mid+40)*2],'move':20,'sight':0,'light':0,'sound':0,'door':1,'ds':0})
    return result
def scene(key,name,folder,journal_key,image,center,scale,grid=0,tokens=()):
    w,h=Image.open(SYSTEM/'assets/adventure/chapter11'/image).size
    factor=2 if image=='train-map.png' else 1
    d={'name':name,'width':w*factor,'height':h*factor,'padding':0,'active':False,'navigation':False,'tokenVision':False,'fog':{'mode':0},'ownership':{'default':0},'grid':{'type':grid,'size':100,'distance':1,'units':'ярд','alpha':0.16,'color':'#e6d4aa'},'levels':[{'_id':'defaultLevel0000','name':'Основной уровень','background':{'src':ART+image,'color':'#1b343c'}}],'initial':{'x':center[0],'y':center[1],'scale':scale},'environment':{'globalLight':{'enabled':True}},'walls':walls() if grid else []}
    if key=='train':d['flags']={ID:{'starterPositions':{'x':1700,'y':630}}}
    return {'key':key,'folder':folder,'journal':journal_key,'data':d,'tokens':list(tokens)}
